#define R iResolution.xy
#define M iMouse
#define Main void mainImage(out vec4 Q, in vec2 U)
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)
float line (vec2 p, vec2 a, vec2 b) {
    return length(p-a-(b-a)*clamp(dot(p-a,b-a)/dot(b-a,b-a),0.,1.));
}
vec2 perp(vec2 u) {return vec2(-u.y,u.x);}

Main {
    Q = A(U);
    vec4 M2 = B(U);
    if (M.z>0.&&M2.z>0.) {

    vec4 c = vec4(sin(vec3(1,2,3)+iTime+
            dot(U-M.xy,perp(M.xy-M2.xy)/length(M.xy-M2.xy))
        ),1);

    Q = max(Q,c*exp(-.5*line(U,M.xy,M2.xy)));
    }
}

Main {

    Q = .99*C(U);

    vec2 d = vec2(cos(float(iFrame)),sin(float(iFrame)));

    for (float i = 0.; i < 300.; i++) {
        U += d;
        vec4 q = A(U);
        if (length(q.w)>.5) {
            Q += .01*max(q,0.);
            break;
        }
    }
}
